  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']

    n = len(segments)
    mins = [seg['minimum'] for seg in segments]
    caps = [seg['capacity'] for seg in segments]
    min_sum = sum(mins)
    max_sum = sum(caps)
    if budget < min_sum or budget > max_sum:
        raise ValueError(f'Budget {budget} out of range [{min_sum},{max_sum}]')

    allocations = mins[:]
    remaining = budget - min_sum

    import heapq
    heap = []
    for i, seg in enumerate(segments):
        if allocations[i] < caps[i]:
            priority = seg['importance'] / (allocations[i] + 1)
            heapq.heappush(heap, (-priority, i))

    while remaining > 0 and heap:
        neg_priority, i = heapq.heappop(heap)
        if allocations[i] >= caps[i]:
            continue  # already full (shouldn't happen if we push correctly)
        allocations[i] += 1
        remaining -= 1
        if allocations[i] < caps[i]:
            priority = segments[i]['importance'] / (allocations[i] + 1)
            heapq.heappush(heap, (-priority, i))

    # If budget not fully allocated (shouldn't happen with valid budget, but safeguard)
    if remaining > 0:
        raise RuntimeError('Could not allocate full budget')

    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    total = sum(allocations)

    return {
        'allocations': allocations,
        'by_name': by_name,
        'total': total
    }"
}
